// src/facets/ground.rs — the facet's own module; src/main.rs adds its two FACET WIRING lines.
// World (src/main.rs) holds player: Vec3, ground: Option<Terrain> and rocks: Option<InstanceGroup>.
use super::World;
use genex::prelude::*;
use genex::{Grass, InstanceGroup, Scatter, Terrain, TerrainLayer, TerrainTexel};

/// Samples a side: 0.5 m apart over 192 m (at most 2049).
const SIDE: u32 = 385;
const SPACING: f32 = 0.5;
const ORIGIN: f32 = -96.0;

/// The ground's height: pure (no world, no clock) and genex::math, so every destination agrees.
fn hills(x: f32, z: f32) -> f32 {
    6.0 * genex::math::sin(x / 23.0) * genex::math::cos(z / 31.0) + 1.5 * genex::math::sin((x + z) / 9.0)
}

/// One control texel per height sample: rock where the ground is steep, grass elsewhere.
fn paint(i: u32) -> TerrainTexel {
    let (x, z) = (ORIGIN + (i % SIDE) as f32 * SPACING, ORIGIN + (i / SIDE) as f32 * SPACING);
    let slope = (hills(x + SPACING, z) - hills(x, z)).abs() / SPACING;
    TerrainTexel::blend(0, 1, (slope * 1.5).min(1.0))
}

pub fn wire(game: &mut Game<World>) {
    game.on_reset(|sim, _, _, gfx| {
        let layers = vec![
            // 0: grass, painted close to the grass's own colour (low presets draw the ground alone)
            TerrainLayer::flat(Color::rgb(70, 100, 44)).with_grass(Grass::meadow(36.0, 0.5)),
            TerrainLayer::flat(Color::rgb(128, 124, 116)), // 1: rock
        ];
        let texels: Vec<TerrainTexel> = (0..SIDE * SIDE).map(paint).collect();
        let made = Terrain::from_fn([SIDE, SIDE], vec2(ORIGIN, ORIGIN), SPACING, hills)
            .and_then(|heights| heights.with_layers(layers))
            .and_then(|layered| layered.with_control(&texels));
        // A refusal (terrain-heights-invalid, -layers-invalid, -control-invalid) changes nothing.
        let Ok(terrain) = made else { return };
        // Rocks stand on the ground: scattered once, at this loading point, drawn as one group.
        let rule = Scatter::new(0.05, &[0, 1]).with_scale(0.6, 1.4).on_flat_ground(0.9).with_cap(4000);
        let spots = terrain.scatter(&rule, vec2(-90.0, -90.0), vec2(90.0, 90.0));
        sim.world.rocks = InstanceGroup::models(&gfx.assets().model("rocks/boulder.glb"), spots).ok();
        let at = sim.world.player;
        sim.world.player = vec3(at.x, terrain.height(at.x, at.z), at.z); // feet on the ground
        sim.world.ground = Some(terrain);
    });
    game.on_draw(|sim, frame, _| {
        frame.tag("ground"); // counts the draws that follow
        if let Some(terrain) = &sim.world.ground {
            frame.terrain(terrain); // one draw, finer near the camera, no pops or cracks
        }
        frame.tag("rocks");
        if let Some(rocks) = &sim.world.rocks {
            frame.group(rocks);
        }
    });
    game.probe("ground", |sim| json!({ "made": sim.world.ground.is_some(), "y": sim.world.player.y }));
}
